var a=[{title:`Avantaje`,text:`Fiecare mână poartă propria sarcină, ceea ce face practică munca pe o singură parte și permite unghiuri de priză pe care o bară fixă poate nu le oferă. Un ramat cu un singur braț sau o împingere cu un singur braț pot arăta diferențe de control între cele două părți. Ganterele se potrivesc adesea mai bine în spații mici decât o instalație completă cu bară, deși salturile între greutăți pot fi mari sau alegerea limitată.`},{title:`Alege greutatea`,text:`Alege o pereche sau o singură ganteră care îți permite să ajungi la repetările-țintă cu mișcare stabilă și câteva repetări în rezervă. Ca începător, poți avea nevoie de sarcini diferite pentru ramat, flexii și împingeri. Dacă următoarea greutate este prea mare, adaugă mai întâi repetări, amplitudine sau control cu cea mai ușoară.`},{title:`Intră în poziție în siguranță`,text:`Pentru un împins de la bancă, stai jos cu ganterele ținute ferm lângă coapse, întinde-te controlat și adu greutățile în poziție fără să le arunci. Pentru ridicările în picioare, ia greutățile cu picioarele și trunchiul într-o poziție stabilă. Nu lăsa greutățile să cadă unde ar putea sări pe picioare, strica podeaua sau lovi pe cineva.`},{title:`Utilizări frecvente`,text:`Genuflexiunile goblet și îndreptatele românești cu gantere antrenează partea inferioară a corpului, ramatul sprijinit și împingerile acoperă partea superioară, iar plimbările cu greutate dezvoltă priza și controlul trunchiului. Dacă ai o singură ganteră, folosește-o pentru mișcările pe o singură parte.`},{title:`Folosirea TrainUp`,text:`În Profil, introdu greutățile ganterelor pe care le ai. Planul tău alege exerciții potrivite cu echipamentul, spațiul și înălțimea tavanului. Nu prescrie greutăți, așa că alegi tu sarcina. Dacă îți notezi sarcinile după un antrenament, scrie-le la fel de fiecare dată, de exemplu „12 kg pe mână”.`}];var r=[{label:`Mayo Clinic: greutăți libere versus aparate`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: tehnica antrenamentului cu greutăți (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var t={sections:a,sources:r};export{t as default,a as sections,r as sources};